package ibc

import (
	"encoding/hex"
	"google.golang.org/protobuf/encoding/protowire"
	"testing"
)

// The send_packet event of gno-realms' z5e_transfer_to_ethereum filetest.
const z5ePacket = ""

func TestDecodePacket(t *testing.T) {
	bz, _ := hex.DecodeString(z5ePacket)
	p, err := DecodePacket(bz)
	if err != nil {
		t.Fatal(err)
	}
	if p.Sequence != 1 || p.SourceClient != "ethereum-1" || p.DestinationClient != "client-0" || p.TimeoutTimestamp != 1234571490 {
		t.Fatalf("bad header fields: %+v", p)
	}
	if len(p.Payloads) != 1 {
		t.Fatalf("payloads: %d", len(p.Payloads))
	}
	pl := p.Payloads[0]
	if pl.SourcePort != "transfer" || pl.DestinationPort != "transfer" || pl.Version != "ics20-1" || pl.Encoding != "application/x-solidity-abi" || len(pl.Value) != 480 {
		t.Fatalf("bad payload: %+v", pl)
	}
}

func TestPath(t *testing.T) {
	got := hex.EncodeToString(Path("eth-0", KindPacketCommitment, 58))
	if got != hex.EncodeToString([]byte("eth-0"))+"01"+"000000000000003a" {
		t.Fatal(got)
	}
}

func TestDecodeAcknowledgement(t *testing.T) {
	ack := []byte(`{"result":"AQ=="}`)
	var bz []byte
	bz = protowire.AppendTag(bz, 1, protowire.BytesType)
	bz = protowire.AppendBytes(bz, ack)
	acks, err := DecodeAcknowledgement(bz)
	if err != nil || len(acks) != 1 || string(acks[0]) != string(ack) {
		t.Fatalf("got %q, %v", acks, err)
	}
}
